public class MovieAccessChecker {static String classifyAccess(String m,String c){if(c.equals("SAME_CLASS"))return "ALLOWED";if(m.equals("public"))return "ALLOWED";if(c.equals("SAME_PACKAGE")&&!m.equals("private"))return "ALLOWED";if(c.equals("SUBCLASS_DIFFERENT_PACKAGE_OWN_TYPE")&&m.equals("protected"))return "ALLOWED";return "DENIED";}public static void main(String[]a){System.out.println(classifyAccess("protected","SAME_PACKAGE"));}}
